struct ExternalTrafficGuard {
    origin: String,
    attempts: Arc<Mutex<Vec<CapturedRequest>>>,
    stop: Arc<AtomicBool>,
    thread: Option<thread::JoinHandle<()>>,
}

impl ExternalTrafficGuard {
    fn start() -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind external traffic guard");
        listener
            .set_nonblocking(true)
            .expect("configure external traffic guard");
        let address = listener
            .local_addr()
            .expect("external traffic guard address");
        let attempts = Arc::new(Mutex::new(Vec::new()));
        let captured = Arc::clone(&attempts);
        let stop = Arc::new(AtomicBool::new(false));
        let stopped = Arc::clone(&stop);
        let thread = thread::spawn(move || {
            while !stopped.load(Ordering::Acquire) {
                match listener.accept() {
                    Ok((mut stream, _)) => {
                        if let Some(request) = read_request(&mut stream) {
                            captured
                                .lock()
                                .expect("capture external attempt")
                                .push(request);
                        }
                        let _ = stream.write_all(
                            b"HTTP/1.1 502 Bad Gateway\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
                        );
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                        thread::sleep(Duration::from_millis(10));
                    }
                    Err(error) => panic!("accept external traffic attempt: {error}"),
                }
            }
        });
        Self {
            origin: format!("http://{address}"),
            attempts,
            stop,
            thread: Some(thread),
        }
    }
}

impl Drop for ExternalTrafficGuard {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::Release);
        let _ = TcpStream::connect(self.origin.trim_start_matches("http://"));
        if let Some(thread) = self.thread.take() {
            thread.join().expect("stop external traffic guard");
        }
    }
}

pub fn assert_split_auth_boundary(home: &Path, router: &MockRouter) {
    let claude_home = home.join(".claude");
    std::fs::create_dir_all(&claude_home).expect("create synthetic Claude profile");
    let credentials = b"{\"claudeAiOauth\":{\"accessToken\":\"synthetic-claude-oauth\",\"refreshToken\":\"synthetic-claude-refresh\",\"expiresAt\":4102444800000,\"subscriptionType\":\"max\",\"scopes\":[\"user:inference\",\"user:mcp_servers\",\"user:file_upload\",\"user:profile\",\"user:sessions:claude_code\"]}}\n";
    std::fs::write(claude_home.join(".credentials.json"), credentials)
        .expect("write synthetic Claude login");

    let request_start = router.requests.lock().expect("read Router capture").len();
    let before = router.inference_requests(CLAUDE.inference_path).len();
    let external = ExternalTrafficGuard::start();
    let output = run_split_auth_capture(home, router, &external.origin);
    assert!(
        output.status.success(),
        "Claude split-auth boundary capture failed; stdout: {}; stderr: {}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(
        !stderr.contains("Claude.ai connectors")
            && !stderr.contains("Remote Control")
            && !stderr.contains("organization policy"),
        "a supported real-client launch repeated the setup limitation: {stderr}"
    );
    assert_eq!(
        std::fs::read(claude_home.join(".credentials.json"))
            .expect("read synthetic Claude login after capture"),
        credentials,
        "Router must leave the released client's stored login byte-identical"
    );

    let requests = router.inference_requests(CLAUDE.inference_path);
    let split_inference = &requests[before..];
    assert!(
        !split_inference.is_empty(),
        "the limitation must not disable Router inference"
    );
    let router_credential = format!("Bearer {}", run_token(CLAUDE));
    for request in split_inference {
        assert_eq!(
            request.header("authorization"),
            Some(router_credential.as_str()),
            "every sampling attempt must carry only the Router credential"
        );
    }
    let capture = {
        let captured = router.requests.lock().expect("read split-auth capture");
        let split_requests = captured[request_start..].to_vec();
        drop(captured);
        // Two discovery paths are real, and neither may carry anything but the
        // Router credential. The wrapper always reads its client-scoped
        // `/api/models` before launch. Claude's own gateway discovery reads the
        // native `/v1/models` as an unawaited start-up task, so a short `-p`
        // run can exit before sending it; its absence is not an inference
        // failure (issue #617). The TUI scenario below, which stays open,
        // asserts that native path deterministically.
        let catalog_requests = split_requests
            .iter()
            .filter(|request| {
                request.method == "GET"
                    && (request.path == "/api/models" || request.path == CLAUDE.catalog_path)
            })
            .collect::<Vec<_>>();
        assert!(
            catalog_requests
                .iter()
                .any(|request| request.path == "/api/models"),
            "the launch must discover the client-scoped Router catalog: {split_requests:?}"
        );
        assert_catalog_credentials(&catalog_requests);
        assert!(
            split_requests.iter().all(|request| {
                request.method != "GET"
                    || !request.path.ends_with("/models")
                    || request.path == "/api/models"
                    || request.path == CLAUDE.catalog_path
            }),
            "Claude crossed into a different protocol catalog: {split_requests:?}"
        );
        format!("{split_requests:?}")
    };
    assert!(
        !capture.contains("synthetic-claude-oauth")
            && !capture.contains("synthetic-claude-refresh"),
        "the stored Claude identity must never reach Router"
    );
    let external_attempts = external
        .attempts
        .lock()
        .expect("read external traffic attempts")
        .clone();
    for attempt in &external_attempts {
        assert_eq!(
            (attempt.method.as_str(), attempt.path.as_str()),
            ("CONNECT", "api.anthropic.com:443"),
            "the offline capture must reject any unexpected external destination: {external_attempts:?}"
        );
        assert!(
            attempt.body.is_empty() && attempt.header("authorization").is_none(),
            "a blocked pre-TLS probe must not expose a request body or credential: {attempt:?}"
        );
    }
}

fn assert_catalog_credentials(requests: &[&CapturedRequest]) {
    let token = run_token(CLAUDE);
    let bearer = format!("Bearer {token}");
    for request in requests {
        let credentials = (request.header("authorization"), request.header("x-api-key"));
        assert!(
            credentials == (Some(bearer.as_str()), None)
                || credentials == (None, Some(token.as_str())),
            "model discovery on {} must carry only the Router credential: {request:?}",
            request.path
        );
    }
}

/// Router-verified Claude capability metadata exists only for the synthetic
/// `future-glm-*` rows. `glm-5.3*` rows are the exact shape Router v1.14.2
/// served for a live z.ai catalog: no capability metadata and the old
/// `provider_advertised_exact_id` spelling (issues #620 and #621).

fn has_verified_profile(id: &str) -> bool {
    id.starts_with("future-glm")
}

pub fn catalog_model(id: &str, owner: &str) -> Value {
    let mut model = json!({
        "id": id, "type": "model", "display_name": id,
        "created_at": "2026-09-05T00:00:00Z", "owned_by": owner
    });
    if owner == "z.ai" && !has_verified_profile(id) {
        model["router_protocols"] = json!(["anthropic"]);
        model["selector_kind"] = json!("provider_advertised_exact_id");
        model["capability_provenance"] = json!({"fields": {}});
    } else if owner == "z.ai" {
        model["client_capabilities"] = json!({
            "claude": {
                "behaves_as": "claude-sonnet-5",
                "source": "provider-protocol:z.ai-anthropic"
            }
        });
    }
    model
}

pub fn seed_home(home: &Path, working_directory: &Path) {
    std::fs::create_dir_all(home).expect("create synthetic Claude profile");
    let mut projects = serde_json::Map::new();
    projects.insert(
        working_directory.to_string_lossy().into_owned(),
        json!({"hasTrustDialogAccepted": true}),
    );
    std::fs::write(
        home.join(".claude.json"),
        json!({
            "hasCompletedOnboarding": true,
            "lastOnboardingVersion": CLAUDE_VERSION,
            "theme": "dark",
            "projects": projects
        })
        .to_string(),
    )
    .expect("seed isolated Claude TUI settings");
}

fn selector_transcript(
    home: &Path,
    router: &MockRouter,
    visible: &[&str],
    choose_default: bool,
) -> String {
    let working_directory = Path::new(env!("CARGO_MANIFEST_DIR"));
    let profile = home.join(".config/link-assistant-router/clients/claude/home");
    seed_home(&profile, working_directory);
    let mut command = wrapper::isolated_pty_command();
    command.args([
        "--server",
        &router.origin,
        "--token",
        "offline-admin",
        "--interactive",
        "claude",
    ]);
    command.cwd(working_directory);
    command.env("HOME", home);
    command.env("XDG_CONFIG_HOME", home.join(".config"));
    command.env("TERM", "xterm-256color");
    command.env("NO_COLOR", "1");
    command.env("NO_PROXY", "127.0.0.1,localhost");
    command.env("no_proxy", "127.0.0.1,localhost");
    command.env("HTTP_PROXY", "http://127.0.0.1:9");
    command.env("HTTPS_PROXY", "http://127.0.0.1:9");
    command.env("ALL_PROXY", "http://127.0.0.1:9");
    let session = PtySession::spawn(command).expect("start Claude TUI through Router");
    session
        .wait_for_screen(
            |text| text.contains('❯'),
            Duration::from_millis(250),
            Duration::from_secs(30),
        )
        .unwrap_or_else(|error| panic!("Claude TUI was not ready: {error}"));
    session.send_text("/model").expect("type /model");
    session
        .wait_for_screen(
            |text| text.contains("/model"),
            Duration::from_millis(100),
            Duration::from_secs(3),
        )
        .expect("settle /model input");
    session.send_key(Key::Enter).expect("open model selector");
    let transcript = session
        .wait_for_screen(
            |text| {
                let compact = text
                    .chars()
                    .filter(|character| !character.is_whitespace())
                    .collect::<String>();
                compact.contains("Selectmodel") && visible.iter().all(|model| text.contains(model))
            },
            Duration::from_millis(250),
            Duration::from_secs(20),
        )
        .unwrap_or_else(|error| {
            panic!(
                "Claude /model did not settle: {error}; routes: {:?}; transcript: {}",
                router.routes(),
                session.transcript_tail(2_000)
            )
        });
    if choose_default {
        choose_default_row_and_prompt(&session, router);
    } else {
        // Let the wrapper drop its active-profile marker normally. Killing the
        // PTY leader can orphan Claude briefly under a container PID 1, making
        // an immediately following reset look active though the TUI is gone.
        session.send_key(Key::Escape).expect("close model selector");
        session
            .wait_idle(Duration::from_millis(200), Duration::from_secs(3))
            .expect("settle closed model selector");
    }
    session.send_text("/exit").expect("type /exit");
    session
        .wait_idle(Duration::from_millis(200), Duration::from_secs(3))
        .expect("settle /exit input");
    session.send_key(Key::Enter).expect("exit Claude TUI");
    session
        .wait_for_exit(Duration::from_secs(10))
        .unwrap_or_else(|error| {
            panic!(
                "Claude TUI did not exit cleanly: {error}; transcript: {}",
                session.transcript_tail(2_000)
            )
        });
    session.kill();
    transcript
}

fn choose_default_row_and_prompt(session: &PtySession, router: &MockRouter) {
    let before = router.inference_requests(CLAUDE.inference_path).len();
    let compact = |text: &str| {
        text.chars()
            .filter(|character| !character.is_whitespace())
            .collect::<String>()
    };
    session.send_text("1").expect("choose the Default row");
    // Text typed while the selector is still closing is dropped, so wait for
    // Claude's confirmation, then for the prompt to reach the input.
    session
        .wait_for_screen(
            |text| compact(text).contains("Setmodelto"),
            Duration::from_millis(300),
            Duration::from_secs(10),
        )
        .unwrap_or_else(|error| {
            panic!(
                "the Default row was not selected: {error}; transcript: {}",
                session.transcript_tail(3_000)
            )
        });
    session
        .send_text(PROMPT)
        .expect("type a prompt on the Default row");
    let typed = compact(PROMPT);
    session
        .wait_for_screen(
            |text| compact(text).contains(&typed),
            Duration::from_millis(200),
            Duration::from_secs(10),
        )
        .unwrap_or_else(|error| {
            panic!(
                "the Default-row prompt was not typed: {error}; transcript: {}",
                session.transcript_tail(3_000)
            )
        });
    session
        .send_key(Key::Enter)
        .expect("send the Default-row prompt");
    let deadline = Instant::now() + Duration::from_secs(30);
    while router.inference_requests(CLAUDE.inference_path).len() == before {
        assert!(
            Instant::now() < deadline,
            "the Default row sent no inference; routes: {:?}; transcript: {}",
            router.routes(),
            session.transcript_tail(3_000)
        );
        thread::sleep(Duration::from_millis(100));
    }
    session
        .wait_idle(Duration::from_millis(500), Duration::from_secs(20))
        .expect("settle the Default-row response");
}

/// The Default row must describe an advertised model, never Claude's built-in
/// family default: on a z.ai-only catalog that default names a model the token
/// cannot reach, so selecting it fails on the next prompt (issue #630).

fn assert_default_row_is_authorized(compact: &str, models: &[(&str, &str)]) {
    let marker = "Usethedefaultmodel(currently";
    let offset = compact
        .find(marker)
        .unwrap_or_else(|| panic!("/model did not describe its Default row: {compact}"));
    let described = compact[offset + marker.len()..]
        .chars()
        .take(120)
        .collect::<String>();
    for family in ["Opus", "Sonnet", "Haiku"] {
        assert!(
            !described.starts_with(family),
            "z.ai-only Default row resolves to the unavailable {family} family: {described}"
        );
    }
    // The reconstructed screen preserves full identities through cursor redraws.
    // Keep the displayed Default identity as exact as the outbound request.
    let shown = described.split(['[', ')']).next().unwrap_or_default();
    assert!(
        models.iter().any(|(model, _)| shown == *model),
        "z.ai-only Default row does not name an advertised model: {described}"
    );
}

fn assert_scenario(models: &[(&str, &str)], visible: &[&str], verify_reset: bool) {
    let router = MockRouter::start_with_models(
        CLAUDE,
        models
            .iter()
            .map(|(id, owner)| catalog_model(id, owner))
            .collect(),
    );
    let home = tempfile::tempdir().expect("temporary Claude home");
    let zai_only = models.iter().all(|(_, owner)| *owner == "z.ai");
    let inference_before = router.inference_requests(CLAUDE.inference_path).len();
    let transcript = selector_transcript(home.path(), &router, visible, zai_only);
    // The TUI stays open long enough for Claude's unawaited gateway discovery
    // to reach the native catalog, so here that path is required (#617).
    let native_discovery = router
        .requests
        .lock()
        .expect("read TUI discovery capture")
        .iter()
        .filter(|request| request.method == "GET" && request.path == CLAUDE.catalog_path)
        .cloned()
        .collect::<Vec<_>>();
    assert!(
        !native_discovery.is_empty(),
        "Claude did not discover its native Router catalog: {:?}",
        router.routes()
    );
    assert_catalog_credentials(&native_discovery.iter().collect::<Vec<_>>());
    assert!(
        !home.path().join(".claude").exists() && !home.path().join(".claude.json").exists(),
        "a default Router launch must not create or change the normal Claude tree"
    );
    let compact = transcript
        .chars()
        .filter(|character| !character.is_whitespace())
        .collect::<String>();
    if zai_only {
        assert_default_row_is_authorized(&compact, models);
        // Every request the Default row caused, the title and the prompt
        // alike, must name an advertised model, never an unauthorized Opus.
        let requests = router.inference_requests(CLAUDE.inference_path);
        assert!(
            requests.len() > inference_before,
            "the Default row sent no inference"
        );
        for request in &requests[inference_before..] {
            let body: Value =
                serde_json::from_slice(&request.body).expect("Claude Default-row JSON");
            let model = body["model"].as_str().expect("exact Default-row model");
            if models
                .iter()
                .any(|(id, owner)| *id == "glm-5.3" && *owner == "z.ai")
            {
                assert_eq!(
                    model, "glm-5.3",
                    "a fresh authorized z.ai Default row must send the flagship ID"
                );
            }

            assert!(
                models.iter().any(|(advertised, _)| *advertised == model),
                "the Default row sent the unadvertised model {model}"
            );
        }
        for unavailable in ["Opus", "Sonnet", "Haiku"] {
            for number in 1..=8 {
                let choice = format!("{number}.{unavailable}");
                assert!(
                    !compact.contains(&choice),
                    "z.ai-only /model exposed the unavailable {unavailable} family: {transcript}"
                );
            }
        }
    }
    for (model, owner) in models {
        if *owner != "z.ai" {
            continue;
        }
        for (offset, _) in compact.match_indices(model) {
            let before = compact[..offset].chars().rev().take(80).collect::<String>();
            let after = compact[offset + model.len()..]
                .chars()
                .take(80)
                .collect::<String>();
            let nearby = format!("{before}{after}");
            for family in ["CustomOpus", "CustomSonnet", "CustomHaiku"] {
                assert!(
                    !nearby.contains(family),
                    "z.ai model attached to a fake family"
                );
            }
        }
    }
    let selected = models
        .iter()
        .find_map(|(model, owner)| (*owner == "z.ai").then_some(*model))
        .unwrap_or(models[0].0);
    let output = run_wrapper_with_model(
        CLAUDE,
        Path::new(env!("CARGO_MANIFEST_DIR")),
        home.path(),
        &router.origin,
        selected,
    );
    let diagnostics = format!(
        "{}{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    // Only a row with verified metadata carries `behavesAs`. For one without,
    // Claude's own `unrecognized_model` note is the honest outcome: Router
    // invents no identity for it, and the request is still served (#621).
    assert!(
        !has_verified_profile(selected)
            || (!diagnostics.contains("unrecognized_model")
                && !diagnostics.contains("isn't described by this version's model catalog")
                && !diagnostics.contains("within 200k tokens")),
        "the verified dynamic model was treated as unknown: {diagnostics}"
    );
    let request = router
        .inference_requests(CLAUDE.inference_path)
        .into_iter()
        .last()
        .expect("selected exact model reaches inference");
    let body: Value = serde_json::from_slice(&request.body).expect("Claude inference JSON");
    assert_eq!(body["model"], selected);
    if models
        .iter()
        .any(|(model, owner)| *model == selected && *owner == "z.ai" && has_verified_profile(model))
    {
        // Which shape the client sends follows the capability identity Router
        // advertises: a fixed `budget_tokens` for some identities, an
        // `adaptive` mode with `output_config.effort` for others. Both are
        // accepted by the live provider — measured directly, HTTP 200 with a
        // signed thinking block either way — so this asserts thinking was
        // requested in *a* supported shape rather than pinning one spelling
        // (issue #565).
        let mode = body["thinking"]["type"]
            .as_str()
            .expect("the verified Claude profile must request a thinking mode");
        assert!(
            matches!(mode, "enabled" | "adaptive"),
            "the verified Claude profile requested an unsupported thinking mode: {body}"
        );
        let maximum = body["max_tokens"]
            .as_u64()
            .expect("Claude inference must include a numeric output limit");
        if mode == "enabled" {
            let budget = body["thinking"]["budget_tokens"]
                .as_u64()
                .expect("enabled Claude thinking must include a numeric budget");
            assert!(
                budget > 0 && budget < maximum,
                "Claude thinking budget must fit below max_tokens: {body}"
            );
        } else {
            // The adaptive mode carries an effort instead of a budget, and the
            // provider reads it from `output_config`.
            let effort = body["output_config"]["effort"]
                .as_str()
                .expect("adaptive Claude thinking must name an effort");
            assert!(
                !effort.is_empty(),
                "adaptive Claude thinking must name a non-empty effort: {body}"
            );
        }
    }
    assert!(
        output.status.success(),
        "Claude did not serve the selected exact model: {diagnostics}"
    );
    // Exercise every custom row, not just the first one used by the TUI
    // scenario. Each selection must reach the offline Router mock verbatim.
    for (model, owner) in models {
        if *owner != "z.ai" || *model == selected {
            continue;
        }
        // Keep each real-client run on an isolated profile so Claude's
        // short-lived background profile holder cannot interfere with the
        // scenario's later reset check.
        let row_home = tempfile::tempdir().expect("temporary exact-row Claude home");
        let output = run_wrapper_with_model(
            CLAUDE,
            Path::new(env!("CARGO_MANIFEST_DIR")),
            row_home.path(),
            &router.origin,
            model,
        );
        assert!(
            output.status.success(),
            "Claude did not serve exact picker row {model}: {}{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        let request = router
            .inference_requests(CLAUDE.inference_path)
            .into_iter()
            .last()
            .expect("selected exact model reaches the offline Router mock");
        let body: Value =
            serde_json::from_slice(&request.body).expect("Claude inference JSON for picker row");
        assert_eq!(body["model"], *model);
    }
    if models
        .iter()
        .any(|(model, owner)| *model == selected && *owner == "z.ai" && has_verified_profile(model))
    {
        let traced = run_wrapper_with_options(
            CLAUDE,
            Path::new(env!("CARGO_MANIFEST_DIR")),
            home.path(),
            &router.origin,
            Some(selected),
            &["--verbose", "--output-format", "stream-json", PROMPT],
        );
        assert!(
            traced.status.success(),
            "Claude verbose thinking capture failed: {}{}",
            String::from_utf8_lossy(&traced.stdout),
            String::from_utf8_lossy(&traced.stderr)
        );
        let trace = String::from_utf8_lossy(&traced.stdout);
        assert!(
            trace.contains(THINKING_TRACE),
            "Claude verbose output did not expose the received reasoning trace: {trace}"
        );
    }

    if verify_reset {
        let output = run_wrapper_with_options(
            CLAUDE,
            Path::new(env!("CARGO_MANIFEST_DIR")),
            home.path(),
            &router.origin,
            Some(selected),
            &["--reset-to-default-configuration", PROMPT],
        );
        assert!(
            output.status.success(),
            "Claude did not serve the exact model after resetting its Router profile: {}{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
        let request = router
            .inference_requests(CLAUDE.inference_path)
            .into_iter()
            .last()
            .expect("post-reset exact model reaches inference");
        let body: Value =
            serde_json::from_slice(&request.body).expect("post-reset Claude inference JSON");
        assert_eq!(body["model"], selected);
    }

    if models.iter().all(|(_, owner)| *owner == "z.ai") {
        let before = router.inference_requests(CLAUDE.inference_path).len();
        let fallback = run_wrapper_with_options(
            CLAUDE,
            Path::new(env!("CARGO_MANIFEST_DIR")),
            home.path(),
            &router.origin,
            None,
            &[PROMPT],
        );
        assert!(
            fallback.status.success(),
            "Claude default/fallback run failed"
        );

        let session = "11111111-2222-4333-8444-555555555555";
        let initial = run_wrapper_with_options(
            CLAUDE,
            Path::new(env!("CARGO_MANIFEST_DIR")),
            home.path(),
            &router.origin,
            Some(selected),
            &["--session-id", session, PROMPT],
        );
        assert!(initial.status.success(), "Claude resumable run failed");
        let resumed = run_wrapper_with_options(
            CLAUDE,
            Path::new(env!("CARGO_MANIFEST_DIR")),
            home.path(),
            &router.origin,
            None,
            &["--resume", session, PROMPT],
        );
        assert!(resumed.status.success(), "Claude resumed run failed");

        let before_subagent = router.inference_requests(CLAUDE.inference_path).len();
        let subagent = run_wrapper_with_options(
            CLAUDE,
            Path::new(env!("CARGO_MANIFEST_DIR")),
            home.path(),
            &router.origin,
            Some(selected),
            &[SUBAGENT_PROMPT],
        );
        assert!(subagent.status.success(), "Claude subagent run failed");

        let requests = router.inference_requests(CLAUDE.inference_path);
        assert!(
            requests.len() >= before_subagent + 2,
            "the Agent tool did not produce a subagent request"
        );
        for request in &requests[before..] {
            let body: Value =
                serde_json::from_slice(&request.body).expect("Claude routed request JSON");
            let model = body["model"].as_str().expect("exact routed model");
            assert!(
                models.iter().any(|(advertised, _)| *advertised == model),
                "main, resumed, fallback, or subagent request used unadvertised model {model}"
            );
        }
    }
}

#[test]
fn current_claude_model_selector_keeps_exact_provider_models_distinct() {
    if !enabled() {
        return;
    }
    assert!(
        command_exists("claude"),
        "the real-client gate requires claude"
    );
    assert_scenario(&[("future-glm-only", "z.ai")], &["future-glm-only"], false);
    assert_scenario(
        &[
            ("future-glm-alpha", "z.ai"),
            ("future-glm-beta", "z.ai"),
            ("future-glm-gamma", "z.ai"),
        ],
        &["future-glm-alpha", "future-glm-beta", "future-glm-gamma"],
        false,
    );
    // The exact rows a z.ai-only v1.14.2 Router served: no capability
    // metadata, yet both must be listed and served (issues #620 and #621).
    assert_scenario(
        &[("glm-5.3", "z.ai"), ("glm-5.3-flash", "z.ai")],
        &["glm-5.3", "glm-5.3-flash"],
        false,
    );
    assert_scenario(
        &[
            ("future-claude-native", "anthropic"),
            ("future-glm-mixed", "z.ai"),
        ],
        &["future-claude-native", "future-glm-mixed"],
        true,
    );
    // An Anthropic-only catalog lists its native rows and serves the exact
    // selection (issue #630).
    assert_scenario(
        &[("future-claude-native", "anthropic")],
        &["future-claude-native"],
        false,
    );
}

/// A model Claude remembered while the catalog authorized it must be refused
/// before launch once the catalog no longer does, with no inference and no
/// silent substitution (issues #577 and #630).

#[test]
fn current_claude_refuses_a_saved_choice_the_changed_catalog_no_longer_authorizes() {
    if !enabled() {
        return;
    }
    assert!(
        command_exists("claude"),
        "the real-client gate requires claude"
    );
    let native = "claude-sonnet-5-5";
    let home = tempfile::tempdir().expect("temporary Claude home");
    let working_directory = Path::new(env!("CARGO_MANIFEST_DIR"));
    let profile = home
        .path()
        .join(".config/link-assistant-router/clients/claude/home");
    seed_home(&profile, working_directory);
    // `CLAUDE_CONFIG_DIR` is the profile itself, where Claude saves `/model`.
    std::fs::write(
        profile.join("settings.json"),
        json!({"model": native}).to_string(),
    )
    .expect("save the /model choice");

    let mixed = MockRouter::start_with_models(
        CLAUDE,
        vec![
            catalog_model(native, "anthropic"),
            catalog_model("future-glm-mixed", "z.ai"),
        ],
    );
    let served = run_wrapper_with_options(
        CLAUDE,
        working_directory,
        home.path(),
        &mixed.origin,
        None,
        &[PROMPT],
    );
    assert!(
        served.status.success(),
        "the saved choice was not served while authorized: {}{}",
        String::from_utf8_lossy(&served.stdout),
        String::from_utf8_lossy(&served.stderr)
    );
    let request = mixed
        .inference_requests(CLAUDE.inference_path)
        .into_iter()
        .last()
        .expect("the saved choice reaches inference");
    let body: Value = serde_json::from_slice(&request.body).expect("Claude inference JSON");
    assert_eq!(body["model"], native);
    assert!(
        wrapper::launcher_diagnostics(home.path())
            .contains("keeping your own Claude model selection"),
        "Router pinned over the saved choice"
    );

    let changed =
        MockRouter::start_with_models(CLAUDE, vec![catalog_model("future-glm-mixed", "z.ai")]);
    let refused = run_wrapper_with_options(
        CLAUDE,
        working_directory,
        home.path(),
        &changed.origin,
        None,
        &[PROMPT],
    );
    let diagnostics = format!(
        "{}{}{}",
        String::from_utf8_lossy(&refused.stdout),
        String::from_utf8_lossy(&refused.stderr),
        wrapper::launcher_diagnostics(home.path())
    );
    assert!(
        !refused.status.success(),
        "a stale saved choice launched: {diagnostics}"
    );
    assert!(diagnostics.contains(native), "{diagnostics}");
    assert!(diagnostics.contains("/model"), "{diagnostics}");
    assert!(
        changed.inference_requests(CLAUDE.inference_path).is_empty(),
        "a stale saved choice sent inference"
    );
}
